// ---- PASS B station steps (generated by scripts/nom_pb1b_cut.py) ----

StationStep networkPhaseColourRows(StationBuild& build) {
    // ---- From the station build (generated by scripts/nom_pb1b_cut.py,
    //      each line checked by scripts/nom_pb1b_verify.py). ----
    const NetworkRunContext& ctx = build.ctx;
    NetStation& st = build.st;
    StationAssembly& R = build.R;
    std::map<int, int>& h2local = R.h2local;
    // ---- End of the bindings ----

    // --- The phase-colour columns' record and birth rows ----------
    // Every present column is recorded for the harvest.  A column whose carried
    // prior did not fold this epoch (cold, stale, erased, before the leveling carry
    // is warm, or refused by the builder) gets one pseudo-observation row, x = 0 at
    // weight 1 / sigma(e)^2: the state's stationary prior.  Within one epoch the
    // column is confounded with its line of sight's band-common ambiguity
    // direction, so without this row the station block would be singular.  The row
    // sits in A_r (not the pre-test diagonal prior), so the within-epoch RAIM
    // replay, which re-adds the assembled rows, keeps it.  Off: nothing runs.
    if (!ctx.knobs.pc_on) return StationStep::Next;
    const Eigen::VectorXd x_lin_pc = st.sm->getStateVector();
    std::vector<std::tuple<Eigen::Index, double, double>> brows;   // (col, w, y)
    std::vector<RowTag> brow_tag;   // one contribution tag per row
    for (const auto& [pc_sat, pc_sidx] : st.sm->getPhaseColourStates()) {
        const int pidx = static_cast<int>(pc_sidx);
        if (pidx < 0 || pidx >= x_lin_pc.size() || !std::isfinite(x_lin_pc(pidx)))
            continue;
        const auto phit = h2local.find(pidx);
        if (phit == h2local.end()) continue;
        const Eigen::Index pcol = static_cast<Eigen::Index>(phit->second);
        const double elev = st.sm->getPhaseColourElevation(pc_sat);
        const bool folded = std::find(R.pc_folded.begin(), R.pc_folded.end(), pcol)
                            != R.pc_folded.end();
        R.pl_pc.push_back(PlPc{pc_sat, pcol, x_lin_pc(pidx), elev, folded});
        if (folded) continue;
        brows.emplace_back(pcol, 1.0 / ctx.knobs.pcStationaryVar(elev),
                           -x_lin_pc(pidx));
        if (std::find(R.pc_planned.begin(), R.pc_planned.end(), pcol)
            != R.pc_planned.end()) {
            ++R.pc_backstop_rows;
            brow_tag.push_back(makeRowTag(ContributionKind::PhaseColourBackstop, pc_sat));
        } else {
            ++R.pc_birth_rows;
            brow_tag.push_back(makeRowTag(ContributionKind::PhaseColourBirth, pc_sat));
        }
    }
    const Eigen::Index nb = static_cast<Eigen::Index>(brows.size());
    if (nb > 0) {
        const Eigen::Index m0 = R.A_s.rows();
        R.A_s.conservativeResize(m0 + nb, Eigen::NoChange);
        R.A_s.bottomRows(nb).setZero();
        R.A_r.conservativeResize(m0 + nb, Eigen::NoChange);
        R.A_r.bottomRows(nb).setZero();
        R.w.conservativeResize(m0 + nb);
        R.y.conservativeResize(m0 + nb);
        for (Eigen::Index k = 0; k < nb; ++k) {
            const auto& [bc_col, bc_w, bc_y] = brows[static_cast<std::size_t>(k)];
            R.A_r(m0 + k, bc_col) = 1.0;
            R.w(m0 + k) = bc_w;
            R.y(m0 + k) = bc_y;
        }
        R.row_tags.insert(R.row_tags.end(), brow_tag.begin(), brow_tag.end());
    }
    return StationStep::Next;
}

void networkPhaseColourBlockColumns(StationCarryFrame& carry) {
    // ---- From the station build (generated by scripts/nom_pb1b_cut.py,
    //      each line checked by scripts/nom_pb1b_verify.py). ----
    StationBuild& build = carry.build;
    const NetworkRunContext& ctx = build.ctx;
    double pl_now_s = build.clock.pl_now_s;
    const int i = build.i;
    NetStation& st = build.st;
    StationAssembly& R = build.R;
    std::map<int, int>& h2local = R.h2local;
    const bool legacy_local_inject = carry.legacy_local_inject;
    const bool do_amb_carry = carry.do_amb_carry;
    const Eigen::VectorXd& x_lin = carry.x_lin;
    // The alias lines of networkPassB_ this function reads, verbatim.
    // Live predicate for F3: the block's rows are coupling rows (A_s/A_r) (the
    // loader warns that the knob is inert without them).  A single const bool, so the
    // off path never reaches a block branch.
    const bool   pl_blk_on = ctx.knobs.pl_blk_on;
    // ---- End of the bindings ----

    if (!(legacy_local_inject && do_amb_carry)) return;
    // Phase-colour state (network.phase_colour_state, section 4.1): the station's carried
    // phase-colour columns as more columns of the same block.  Each enters as a
    // predicted copy of its entry (the Gauss-Markov transition: value and every
    // border coefficient times phi = exp(-gap / tau), variance
    // phi^2 var + sigma(e)^2 (1 - phi^2)), and the builder scales its harvested
    // cross covariances by phi.  A column with no live carry (cold, stale, or
    // erased) is not pushed: it gets a birth row after the carry section.  The
    // copies are reserved to their maximum count before the first push, so no
    // LocalBlockCol::lc dangles (the receiver clock's pattern).
    std::vector<LocalBlockCol>& pc_bc = carry.pc_bc;
    std::vector<LocalCarry>& pc_pred = carry.pc_pred;
    if (ctx.knobs.pc_on && pl_blk_on) {
        const auto& pcs = st.sm->getPhaseColourStates();
        pc_pred.reserve(pcs.size());
        for (const auto& [pc_sat, pc_sidx] : pcs) {
            const int pidx = static_cast<int>(pc_sidx);
            if (pidx < 0 || pidx >= x_lin.size() || !std::isfinite(x_lin(pidx))) continue;
            const auto phit = h2local.find(pidx);
            if (phit == h2local.end()) continue;   // no phase row this epoch
            const LocalCarry* pit =
                net::getLos(ctx.entities.los, static_cast<int>(i), pc_sat, &net::LosState::pc);
            if (pit == nullptr) continue;           // cold: birth row
            const double pgap = pl_now_s - pit->last_seen_s;
            if (!(pgap >= 0.0) || pgap > ctx.knobs.pc_max_gap_s) continue;   // stale: birth row
            const double phi = std::exp(-pgap / ctx.knobs.pc_tau_s);
            const double s2  = ctx.knobs.pcStationaryVar(
                st.sm->getPhaseColourElevation(pc_sat));
            const double pvar = phi * phi * pit->var + s2 * (1.0 - phi * phi);
            if (!(pvar > 0.0) || !std::isfinite(pvar)) continue;
            pc_pred.push_back(*pit);
            LocalCarry& pr = pc_pred.back();
            pr.value_abs *= phi;
            for (CoupledShared& cs : pr.coupling) cs.coeff *= phi;
            for (double& c : pr.shx_coef) c *= phi;   // shared-history terms: empty off
            LocalBlockCol pcol{static_cast<Eigen::Index>(phit->second), x_lin(pidx),
                               &pr, pvar, std::max(0.0, pgap), /*vce_fac=*/1.0};
            pcol.phi   = phi;
            pcol.is_pc = true;
            if (const auto col_sat = SatId::parse(pc_sat))   // its block row's tag
                pcol.sat = *col_sat;
            pc_bc.push_back(pcol);
            R.pc_planned.push_back(pcol.col);
        }
    }
}

// ---- End of the PASS B station steps ----

// ---- Harvest half (generated by scripts/nom_hv1_cut.py) ----

void networkHarvestPhaseColourStation(NetworkRun& run, const NetworkEpoch& ep,
                                      HarvestBorder& border, const StationHarvestBlock& sb,
                                      std::size_t i, EpochEvents& events) {
    // ---- From the run, the epoch and the harvest (generated by
    //      scripts/nom_hv1_cut.py, each line checked by scripts/nom_hv1_verify.py). ----
    NetworkRunContext& ctx = run.ctx;
    std::vector<NetStation>& stations = run.setup.stations;
    const std::vector<int>& est_index_of = ep.assembly.est_index_of;
    const std::vector<StationAssembly>& asm_res = ep.assembly.asm_res;
    double pl_now_s = ep.clock.pl_now_s;
    const bool   carry_cpl_cond = ctx.knobs.carry_cpl_cond;
    SharedHistoryHarvest& shx_h = border.shx_h;
    const StationAssembly& R = asm_res[i];
    const std::size_t est_idx = static_cast<std::size_t>(est_index_of[i]);
    const std::vector<Eigen::Index>& cols = sb.cols;
    const Eigen::VectorXd& xr = sb.xr;
    const std::shared_ptr<PlHarvestBlock>& hblk = sb.blk;
    const Eigen::Index pc_row0 = sb.rowOf(BlockSegment::PhaseColour);
    const bool pc_in_cols = ctx.knobs.pc_on && !R.pl_pc.empty();
    EpochEvents::Harvest& harvest_ev = events.harvest;   // written
    // ---- End of the bindings ----
    // Stash each phase-colour column's posterior (the estimate, its pure
    // conditional variance, its border regression) and its row of the station's
    // harvest block, so the next epoch folds it jointly with the ambiguities it
    // shares the phase rows with.  The coupling carry is the posture's (the
    // loader requires it); a column whose regression fails is not stashed and is
    // born again next epoch (counted).
    if (!(pc_in_cols && carry_cpl_cond)) return;
    const double t_week_pc = std::floor(pl_now_s / 604800.0);
    const double t_tow_pc  = pl_now_s - 604800.0 * t_week_pc;
    for (std::size_t k = 0; k < R.pl_pc.size(); ++k) {
        const PlPc& pp = R.pl_pc[k];
        if (pp.col < 0 || pp.col >= xr.size()) { ++ctx.counters.n_pc_stash_fail; continue; }
        const double value_abs = pp.x_lin + xr(pp.col);
        Eigen::VectorXd pcross;
        auto hc = networkHarvestColumn(run, ep, border, est_idx, pp.col, hblk ? &cols : nullptr,
                                                        hblk ? &pcross : nullptr);
        const double var = hc.first;
        if (!std::isfinite(value_abs) || !(var > 0.0) || !std::isfinite(var)) {
            ++ctx.counters.n_pc_stash_fail;
            continue;
        }
        LocalCarry ent{value_abs, var, pl_now_s, std::move(hc.second)};
        const Eigen::Index prow = pc_row0 + static_cast<Eigen::Index>(k);
        if (hblk && pcross.size() == hblk->C.rows() && prow < hblk->C.rows()) {
            hblk->C.row(prow) = pcross.transpose();
            ent.blk     = hblk;
            ent.blk_idx = static_cast<int>(prow);
        }
        net::putLos(ctx.entities, static_cast<int>(i), pp.sat, &net::LosState::pc) = std::move(ent);
        networkSharedHistoryNoteEntry(shx_h, est_idx, pp.col, SharedHistoryMap::Pc,
                                      static_cast<int>(i), pp.sat);   // shared history; no-op off
        ++ctx.counters.n_pc_stash;
        ctx.counters.pc_abs_sum += std::abs(value_abs);
        ctx.counters.pc_sq_sum  += value_abs * value_abs;
        if (ctx.knobs.pc_trace)
            harvest_ev.pc_trace_rows.push_back(fmt::format(
                "{:.0f},{:.1f},{},{},{:.2f},{:.6f},{:.6f},{}\n",
                t_week_pc, t_tow_pc, stations[i].name, pp.sat, pp.elev_deg,
                value_abs, std::sqrt(var), pp.carried ? 1 : 0));
    }
}

void networkPrunePhaseColour(NetworkRun& run, const NetworkEpoch& ep) {
    // ---- From the run, the epoch and the harvest (generated by
    //      scripts/nom_hv1_cut.py, each line checked by scripts/nom_hv1_verify.py). ----
    NetworkRunContext& ctx = run.ctx;
    double pl_now_s = ep.clock.pl_now_s;
    // ---- End of the bindings ----
    // Prune phase-colour entries past the maximum gap.  Such an entry would
    // not be folded anyway (the inject re-births the line of sight); the prune keeps
    // the map to the live lines of sight and counts the edge.  The horizon is the
    // registry's (network.phase_colour_max_gap_s, the same double).
    if (ctx.knobs.pc_on)
        carryGapPrune(ctx.entities.los, &net::LosState::pc, pl_now_s,
                      ctx.params.spec(NetworkParamKind::PhaseColour).gap_horizon_s,
                      [&](const auto&, const auto&) {
                          ++ctx.counters.n_pc_gap_prune;
                          prmRespond(ctx.counters.prm_resp, ResponseSite::PcGapPrune);
                      });
}

// ---- End of the harvest half ----

// ---- Run-end report (moved here from network/carry/LevelingCarryRunEnd.cpp, beside the harvest) ----

// Run-end report: the phase-colour state (LGM).
int networkPhaseColourRunEnd(const NetworkRunEndView& v) {
    const NetworkRunContext& ctx = v.ctx;
    const std::shared_ptr<spdlog::logger>& log = v.log;

    // The phase-colour state's edges (invariant #4: the run-end counters are the
    // ON-path telemetry).
    if (!ctx.knobs.pc_on) return 0;
    const auto& C = ctx.counters;
    const double n = static_cast<double>(C.n_pc_stash);
    log->info("Network: phase-colour state: {} birth row(s), {} carried fold(s) "
              "through the block, {} by the per-column fallback, {} backstop birth row(s); "
              "{} entries harvested (rms estimate {:.2f} mm, mean |x| {:.2f} mm), {} harvest "
              "refusal(s); {} erased by the RAIM attribution, {} by the gross line-of-sight "
              "screen, {} pruned past {:.0f} s; {} live at the end.",
              C.n_pc_birth_rows, C.n_pc_block_folds, C.n_pc_fallback_folds,
              C.n_pc_backstop_rows, C.n_pc_stash,
              n > 0.0 ? 1e3 * std::sqrt(C.pc_sq_sum / n) : 0.0,
              n > 0.0 ? 1e3 * C.pc_abs_sum / n : 0.0, C.n_pc_stash_fail,
              C.n_pc_erase_raim, C.n_pc_erase_gross, C.n_pc_gap_prune,
              ctx.knobs.pc_max_gap_s, net::present(ctx.entities.los, &net::LosState::pc));
    if (C.n_pc_stash > 0 && C.n_pc_block_folds + C.n_pc_fallback_folds == 0)
        log->warn("Network: the phase-colour state was harvested but never "
                  "folded a carried prior: it acted only through its birth rows, i.e. as "
                  "white noise.  Read the run as the state OFF, not as its test.");
    if (C.n_pc_backstop_rows > 0)
        log->warn("Network: {} planned carried phase-colour column(s) did not "
                  "fold (refused by the block builder or the per-column route) and fell "
                  "back to the birth prior.", C.n_pc_backstop_rows);
    return 0;
}

